def _table(source: str, target: str) -> dict:
    """Match cnchar's indexOf behavior: first occurrence wins."""
    if len(source) != len(target):
        raise ValueError("Mismatched dictionary lengths")
    mapping = {}
    for a, b in zip(source, target):
        mapping.setdefault(a, b)
    return str.maketrans(mapping)


_SIMPLE_TO_SPARK = _table(SPARK_SIMPLE, SPARK_CHARS)
_SPARK_TO_SIMPLE = _table(SPARK_CHARS, SPARK_SIMPLE)
_SIMPLE_TO_TRAD = _table(TRAD_SIMPLE, TRAD_CHARS)
_TRAD_TO_SIMPLE = _table(TRAD_CHARS, TRAD_SIMPLE)

_TYPES = {"simple", "trad", "spark", "mars"}


def convert(text: str, source: str, target: str) -> str:
    """Convert between simple, trad and spark (alias: mars)."""
    if source not in _TYPES or target not in _TYPES:
        raise ValueError("source/target must be simple, trad, spark or mars")
    source = "spark" if source == "mars" else source
    target = "spark" if target == "mars" else target
    if source == target:
        return text
    if source == "trad":
        text = text.translate(_TRAD_TO_SIMPLE)
    elif source == "spark":
        text = text.translate(_SPARK_TO_SIMPLE)
    if target == "trad":
        return text.translate(_SIMPLE_TO_TRAD)
    if target == "spark":
        return text.translate(_SIMPLE_TO_SPARK)
    return text


def simple_to_spark(text: str) -> str:
    return convert(text, "simple", "spark")


def spark_to_simple(text: str) -> str:
    return convert(text, "spark", "simple")


def trad_to_spark(text: str) -> str:
    return convert(text, "trad", "spark")


def spark_to_trad(text: str) -> str:
    return convert(text, "spark", "trad")


def simple_to_trad(text: str) -> str:
    return convert(text, "simple", "trad")


def trad_to_simple(text: str) -> str:
    return convert(text, "trad", "simple")


def to_mars(text: str, source: str = "simple") -> str:
    return convert(text, source, "spark")


def from_mars(text: str, target: str = "simple") -> str:
    return convert(text, "spark", target)


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="cnchar Chinese/Mars text converter")
    parser.add_argument("text", help="Text to convert")
    parser.add_argument("--source", choices=sorted(_TYPES), default="simple")
    parser.add_argument("--target", choices=sorted(_TYPES), default="spark")
    args = parser.parse_args()
    print(convert(args.text, args.source, args.target))
